/**
 * Demo catalog. Every brand, product, seller and ASIN here is FICTIONAL.
 * ASINs use the `B0AISLE…` pattern so they're recognisable as Aisle demo
 * fixtures, and all prices are generated by the simulator in ./simulate.ts.
 * Nothing here represents a real Amazon listing or price.
 */
import type { MarketplaceCode } from "@/lib/marketplaces";

export type DemoShape = "tub" | "bottle" | "jar" | "box" | "serum" | "headphones" | "pouch";

export interface DemoVariant {
  asin: string;
  attributes: Record<string, string>;
  sizeText: string;
  /** Baseline price in major units (simulation perturbs it over time). */
  base: number;
  /** Reference ("M.R.P." / list) price in major units, when the listing shows one. */
  list?: number;
}

export interface DemoFamily {
  key: string;
  marketplace: MarketplaceCode;
  brand: string;
  title: string;
  category: string[];
  parentAsin: string | null;
  dimensions: string[];
  shape: DemoShape;
  hue: number;
  seller: { id: string; name: string; isAmazon: boolean };
  /** When true, the simulated provider pretends it could only discover some variants. */
  partialDiscovery?: boolean;
  variants: DemoVariant[];
}

let n = 0;
const asin = () => `B0AISLE${String(++n).padStart(3, "0")}`;

const v = (attributes: Record<string, string>, sizeText: string, base: number, list?: number): DemoVariant => ({
  asin: asin(),
  attributes,
  sizeText,
  base,
  list,
});

