export const DEMO_REFERENCE_BRAND = "Lumen Nutrition";

const byAsin = new Map<string, { family: DemoFamily; variant: DemoVariant }>();
for (const family of DEMO_FAMILIES) for (const variant of family.variants) byAsin.set(variant.asin, { family, variant });

export function findDemoListing(asin: string) {
  return byAsin.get(asin) ?? null;
}

export function findDemoFamilyByParent(asin: string) {
  return DEMO_FAMILIES.find((f) => f.parentAsin === asin) ?? null;
}

